import{_ as t,o as a,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Task — G5 Task Management (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g5-task-management/task.md","filePath":"mobile/features/g5-task-management/task.md"}'),n={name:"mobile/features/g5-task-management/task.md"};function c(l,e,r,s,h,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="task-—-g5-task-management-mobile" tabindex="-1">Task — G5 Task Management (Mobile) <a class="header-anchor" href="#task-—-g5-task-management-mobile" aria-label="Permalink to &quot;Task — G5 Task Management (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a></p><h2 id="task-list-fr-3-6-4" tabindex="-1">Task List (FR 3.6.4) <a class="header-anchor" href="#task-list-fr-3-6-4" aria-label="Permalink to &quot;Task List (FR 3.6.4)&quot;">​</a></h2><ul><li>[ ] <code>GET /tasks?page&amp;size&amp;sort&amp;direction&amp;status&amp;type&amp;search&amp;campaignId</code> — filter UI: status/type/search/campaignId.</li><li>[ ] Item hiển thị: tên, type badge, status badge màu, assignee avatar/tên, dueDate, campaign.</li><li>[ ] Pull-to-refresh + infinite scroll (page-based).</li><li>[ ] Client thấy TOÀN BỘ Task trong Workspace (Q13) — KHÔNG tự thêm filter ẩn theo role, chỉ filter UI chuẩn như Manager/Creator.</li></ul><h2 id="task-detail" tabindex="-1">Task Detail <a class="header-anchor" href="#task-detail" aria-label="Permalink to &quot;Task Detail&quot;">​</a></h2><ul><li>[ ] Gọi cả <code>GET /tasks/{id}/workflow</code> (metadata) + <code>GET /tasks/{id}/review</code> (action-gating) — show/hide nút theo <code>allowedActions</code> của chính response, không tự suy luận rule ở client.</li><li>[ ] Header: tên, type, status badge, reviewStep (nếu IN_REVIEW: &quot;Đang chờ Manager&quot;/&quot;Đang chờ Client&quot;).</li><li>[ ] Block info: description, dueDate, publishDate, assignee, campaign, inputReferences.</li><li>[ ] Tab &quot;Lịch sử duyệt&quot; — <code>GET /tasks/{id}/approvals?cursor&amp;limit</code>.</li><li>[ ] Preview nội dung Post (type=POST) — <strong>chặn bởi mục 8 câu 2, chưa quyết định có làm không, đọc <code>TaskPostResponse</code> trước nếu làm</strong>.</li></ul><h2 id="status-transitions" tabindex="-1">Status transitions <a class="header-anchor" href="#status-transitions" aria-label="Permalink to &quot;Status transitions&quot;">​</a></h2><ul><li>[ ] <code>canStart</code> → <code>POST /start</code> body <code>{expectedRevision}</code>.</li><li>[ ] <code>canSubmit</code> → <code>POST /submit</code> body <code>{expectedRevision, expectedApprovalRound, expectedPostContentVersion}</code>.</li><li>[ ] <code>canWithdraw</code> → <code>POST /withdraw</code> body <code>{expectedRevision, expectedApprovalRound}</code>.</li><li>[ ] <code>canApprove</code> → <code>POST /approve</code> body <code>{expectedRevision, expectedApprovalRound, expectedStep, expectedPostContentVersion, comment?}</code> — chỉ hiện nếu role khớp <code>reviewStep</code> hiện tại.</li><li>[ ] <code>canReject</code> → dialog nhập <code>comment</code> <strong>bắt buộc ở UI</strong> (DTO không <code>@NotBlank</code>) → <code>POST /reject</code> cùng shape approve.</li><li>[ ] Optimistic update mọi transition — rollback + refetch <code>workflow</code>+<code>review</code> khi lỗi (không chỉ revert giá trị cũ, vì cũng đã stale).</li><li>[ ] Xử lý 409 conflict (<code>expectedRevision</code>/<code>expectedApprovalRound</code> lệch) — thông báo thân thiện &quot;Task đã được cập nhật, đang tải lại...&quot;, không lỗi generic (mục 8 câu 3).</li></ul><h2 id="kanban-board-fr-3-6-7-v1-—-1-kieu-board" tabindex="-1">Kanban Board (FR 3.6.7, V1 — 1 kiểu board) <a class="header-anchor" href="#kanban-board-fr-3-6-7-v1-—-1-kieu-board" aria-label="Permalink to &quot;Kanban Board (FR 3.6.7, V1 — 1 kiểu board)&quot;">​</a></h2><ul><li>[ ] 4 cột: TODO/IN_PROGRESS/IN_REVIEW/FINISHED (CANCELLED hiển thị riêng, không kéo thả).</li><li>[ ] Kéo card chỉ cho phép theo transition hợp lệ: TODO→IN_PROGRESS (start, chỉ Creator), IN_PROGRESS→IN_REVIEW (submit, chỉ Creator), IN_REVIEW→FINISHED (approve, đúng role theo reviewStep), IN_REVIEW→IN_PROGRESS (reject — mở dialog nhập comment trước khi commit, không chuyển cột im lặng).</li><li>[ ] Kéo không hợp lệ → card bật lại vị trí cũ + toast lỗi, không gọi API.</li><li>[ ] Dùng cùng cache key với Task Detail (theo <code>taskId</code>) để tránh lệch state giữa List/Kanban/Detail.</li></ul><h2 id="comment-thread-fr-3-6-3" tabindex="-1">Comment Thread (FR 3.6.3) <a class="header-anchor" href="#comment-thread-fr-3-6-3" aria-label="Permalink to &quot;Comment Thread (FR 3.6.3)&quot;">​</a></h2><ul><li>[ ] <code>GET /tasks/{id}/comments?cursor&amp;limit</code> — list cursor-based.</li><li>[ ] Compose box: text + mention autocomplete (<code>GET /comment-members?search</code>) + đính kèm ảnh (tối đa 5 ảnh, mỗi ảnh ≤5MB, JPEG/PNG/WebP — validate client trước khi gọi API).</li><li>[ ] Upload ảnh qua <code>POST /comment-uploads</code> (multipart) lấy <code>attachmentIds</code> trước, rồi <code>POST /comments</code> với <code>clientRequestId</code> (UUID) cho optimistic-send + idempotent retry.</li><li>[ ] Tái dùng UI picker camera/gallery đã làm ở G2 Creator Upload, chỉ đổi target endpoint.</li><li>[ ] Render ảnh qua <code>GET /comment-uploads/{id}/content</code> trong <code>&lt;Image&gt;</code>, <strong>không mở trong WebView</strong> (response có <code>Content-Security-Policy: sandbox</code>).</li><li>[ ] Comment vẫn khả dụng trên Task FINISHED/CANCELLED — không ẩn tab theo status.</li></ul><h2 id="realtime-quyet-đinh-đa-chot-—-polling-xem-spec-muc-5" tabindex="-1">Realtime (quyết định đã chốt — polling, xem spec mục 5) <a class="header-anchor" href="#realtime-quyet-đinh-đa-chot-—-polling-xem-spec-muc-5" aria-label="Permalink to &quot;Realtime (quyết định đã chốt — polling, xem spec mục 5)&quot;">​</a></h2><ul><li>[ ] <code>refetchInterval</code> 15-30s khi Task Detail đang mở hoặc app vào foreground — không có WS topic riêng cho status/comment, chỉ dùng polling nhẹ cho V1.</li></ul><h2 id="business-rules-can-enforce-o-client-approval-sequence-fr-3-6-9" tabindex="-1">Business rules cần enforce ở client (Approval Sequence FR 3.6.9) <a class="header-anchor" href="#business-rules-can-enforce-o-client-approval-sequence-fr-3-6-9" aria-label="Permalink to &quot;Business rules cần enforce ở client (Approval Sequence FR 3.6.9)&quot;">​</a></h2><ul><li>[ ] Chỉ Creator đang là assignee thấy nút Start/Submit/Withdraw.</li><li>[ ] Approve/Reject chỉ hợp lệ role khớp <code>reviewStep</code> hiện tại.</li><li>[ ] Withdraw chỉ hợp lệ trước Manager decision (không còn ở reviewStep=CLIENT).</li><li>[ ] FINISHED không tự động publish — không hiện action &quot;publish&quot; nào ở G5.</li></ul><h2 id="stretch-cat-neu-thieu-thoi-gian" tabindex="-1">Stretch (cắt nếu thiếu thời gian) <a class="header-anchor" href="#stretch-cat-neu-thieu-thoi-gian" aria-label="Permalink to &quot;Stretch (cắt nếu thiếu thời gian)&quot;">​</a></h2><ul><li>[ ] Calendar Task View (FR 3.6.5).</li><li>[ ] 2 kiểu Kanban board còn lại (group theo assignee/type).</li></ul><h2 id="chua-lam-out-of-scope-g5-xem-spec-muc-7" tabindex="-1">Chưa làm / out of scope G5 (xem spec mục 7) <a class="header-anchor" href="#chua-lam-out-of-scope-g5-xem-spec-muc-7" aria-label="Permalink to &quot;Chưa làm / out of scope G5 (xem spec mục 7)&quot;">​</a></h2><ul><li>[ ] Không làm: Content Editor (FR 3.6.10, Yjs realtime), Gantt Timeline View (FR 3.6.6 — loại hẳn, judgment call cần user duyệt lại), Identify Task Detail/Assign Task (FR 3.6.1/3.6.2).</li></ul><h2 id="rui-ro-can-chot-truoc-khi-code-xem-spec-muc-8" tabindex="-1">Rủi ro cần chốt trước khi code (xem spec mục 8) <a class="header-anchor" href="#rui-ro-can-chot-truoc-khi-code-xem-spec-muc-8" aria-label="Permalink to &quot;Rủi ro cần chốt trước khi code (xem spec mục 8)&quot;">​</a></h2><ol><li>Realtime polling vs WS topic riêng — xác nhận trước khi code, đổi sau tốn công refactor cache layer.</li><li>Preview nội dung Post trong Task Detail — quyết định có làm không, đọc <code>TaskPostResponse</code> nếu làm.</li><li>Conflict UX 409 — thiết kế rõ thông báo lỗi, tình huống dễ gặp trên mobile (nhiều người xem/sửa, mạng chậm).</li><li>Gantt loại bỏ hoàn toàn — judgment call của spec, cần user duyệt lại trước khi chốt implementation.</li><li>5 loại TaskType chỉ POST có content workflow — LIVESTREAM/SURVEY/EVENT_PLAN/PRESS_RECOMMENDATION chỉ hiện metadata khung sườn, không màn hình chuyên biệt.</li></ol>',22)])])}const p=t(n,[["render",c]]);export{m as __pageData,p as default};
